import osimport socketimport tkinterfrom tkinter import filedialogmw = tkinter.Tk()mw.geometry('300x150')cd = os.getcwd()#cd = '/home/eric/Documents'mw.sourceFoler = ''mw.sourceFile = ''#def chooseDir():#    mw.sourceFolder = filedialog.askdirectory(parent=mw, initialdir = '/',  title = 'Select Directory')  #b_chooseDir = tkinter.Button(mw, text = "Choose Folder", width = 20, height = 3, command = chooseDir)#b_chooseDir.place(x=50,y=50)#b_chooseDir.width = 100def chooseFile():    mw.sourceFile = filedialog.askopenfilename(parent = mw, initialdir = cd, title = "Choose file?")    #mw.withdraw()b_chooseFile = tkinter.Button(mw, text= 'Choose File',width = 20, height = 3, command = chooseFile)b_chooseFile.place(x =0, y = 0)b_chooseFile.width = 100mw.mainloop()#print(mw.sourceFolder)#print(mw.sourceFile)fn = mw.sourceFile # File Nameof = open(mw.sourceFile,'rb')br = of.read()# incase in mllpres = br.decode()res = 'filename: {}\n'.format(fn) + resif res[0] != chr(11):    res = chr(11) + resif res.find(chr(13)) == -1:    nr = res.replace('\n','\r')else:    nr = resif nr.find(chr(28)) == -1:    cma = chr(28) + '\r' # close message ascii    if nr[-1] != 13:        cma = '\r' + cma    nr += cmabr = nr.encode()ba = bytearray(br)print('File wrapped, preparing to send')ip_n_port = ('192.168.15.103',4433)o_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)print('type(o_sock) = {}'.format(type(o_sock)))try:    o_sock.connect(ip_n_port)    print('connect called for {}'.format(ip_n_port))except ValueError as e:    print('Error on connect attempt: {}'.format(e))print('Attempting to send message')try:    o_sock.sendall(br)except ValueError as e:    print('write Error encountered:\n{}'.format(e))